    anchors = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(anchors) < 2:
        return out

    # The marker surrounded by the larger nonzero pattern marks the source.
    def nearby(a):
        r, c = a
        return sum(
            1 for i, row in enumerate(grid) for j, v in enumerate(row)
            if v != 0 and v != 5 and abs(i-r) <= 4 and abs(j-c) <= 4
        )

    source = max(anchors, key=nearby)
    target = anchors[1] if source == anchors[0] else anchors[0]
    dr, dc = target[0] - source[0], target[1] - source[1]

    # Translate all colored cells except the marker itself; the destination
    # marker is replaced by the translated pattern.
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v = grid[r][c]
            if v != 0 and v != 5:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    out[nr][nc] = v
    out[target[0]][target[1]] = 0
    return out
